insert into ragams (id, name, description, time_of_day) values
  ('bhairavi', 'Bhairavi', 'A profound and expressive raga often called the queen of ragas. Its rich, emotive phrases have been used for centuries in devotional and contemplative music.', 'morning'),
  ('neelambari', 'Neelambari', 'The lullaby raga, used for centuries to induce sleep. Its gentle, descending phrases calm the nervous system.', 'night'),
  ('sahana', 'Sahana', 'An emotive raga of longing and surrender. Its contemplative phrases draw the listener inward, ideal for breathwork and presence.', 'evening'),
  ('hindolam', 'Hindolam', 'A pentatonic raga of deep serenity. Its simple, swinging phrases create a meditative space that requires no effort to enter.', 'morning'),
  ('mohanam', 'Mohanam', 'A bright, uplifting pentatonic raga. Its joyful, ascending phrases energize the mind and lift the spirit without overstimulating.', 'afternoon'),
  ('kalyani', 'Kalyani', 'An expansive, luminous raga associated with auspiciousness. Its wide-ranging phrases open the chest and create a feeling of spaciousness.', 'evening'),
  ('todi', 'Todi', 'A majestic morning raga of quiet intensity. Its slow, deliberate phrases demand full attention and reward it with profound stillness.', 'morning');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('bhairavi-focus-01', 'Morning Bhairavi — Deep Focus', 'bhairavi', '{focus}', '{grounding,concentration,warmth}', 'A grounding Bhairavi improvisation with percussion. Its rich phrases sharpen concentration and sustain deep focus.', null, '2025-01-12', 'Home studio, Portland', 2700, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-01-12T00:00:00Z'),
  ('bhairavi-meditate-01', null, 'bhairavi', '{meditate,focus}', '{devotional,introspective,warmth}', 'Recorded before sunrise in Chennai. A slow, deeply internal Bhairavi that builds from silence into rich, emotive phrases.', 'I woke at 4am and the city was completely still. The shruti box was already warm from the night before. This one played itself.', '2024-11-20', 'Before sunrise, Chennai', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-11-20T00:00:00Z'),
  ('bhairavi-sleep-01', null, 'bhairavi', '{sleep}', '{gentle,surrender,rain}', 'A late-night Bhairavi after a long rain. Softer and slower than the morning sessions, letting the phrases dissolve into silence.', null, '2025-02-14', 'Late night after rain, Portland', 5400, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-02-14T00:00:00Z'),
  ('bhairavi-focus-02', null, 'bhairavi', '{focus}', '{steady,concentration,percussion}', 'A rhythmically driven Bhairavi with strong percussion anchoring the improvisation. Good for sustained work sessions.', null, '2025-03-08', 'Sunday morning, home studio', 2700, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', false, '2025-03-08T00:00:00Z'),
  ('bhairavi-meditate-02', 'Bhairavi at Dawn', 'bhairavi', '{meditate}', '{devotional,stillness,dawn}', 'An early morning session near the Mylapore temple quarter. The temple bells are faintly audible in the background.', 'Kapaleeshwarar temple bells started ringing midway through. I didn''t stop — they became part of the raga.', '2024-09-15', 'Mylapore temple quarter, Chennai', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-09-15T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('neelambari-sleep-01', 'Neelambari Lullaby', 'neelambari', '{sleep}', '{calm,surrender,warmth}', 'The quintessential lullaby raga with gentle percussion. Its descending phrases calm the nervous system and ease you into rest.', null, '2024-12-03', 'At dusk by the Willamette', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-12-03T00:00:00Z'),
  ('neelambari-sleep-02', null, 'neelambari', '{sleep}', '{silence,gentle,minimal}', 'A sparse, unhurried Neelambari with long pauses between phrases. Each note is placed deliberately, then allowed to fade.', null, '2025-01-28', 'Quiet evening, Portland', 5400, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-01-28T00:00:00Z'),
  ('neelambari-meditate-01', null, 'neelambari', '{meditate,sleep}', '{contemplative,midnight,stillness}', 'An after-midnight Neelambari that blurs the line between meditation and sleep. The phrases are slow enough to follow with the breath.', 'This was originally meant for sleep but friends said it kept them present rather than drowsy. So it lives in both worlds.', '2025-02-01', 'After midnight, home studio', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-02-01T00:00:00Z'),
  ('neelambari-sleep-03', 'Neelambari for Rest', 'neelambari', '{sleep}', '{lullaby,warmth,traditional}', 'A traditional rendering of Neelambari in the style it has been sung for centuries — as a lullaby. Recorded during a visit to Thanjavur.', null, '2024-10-22', 'Guest room session, Thanjavur', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', false, '2024-10-22T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('sahana-meditate-01', 'Sahana — Contemplation', 'sahana', '{meditate}', '{contemplative,longing,surrender}', 'A deeply emotive Sahana improvisation for meditation. Its contemplative phrases draw the listener inward, ideal for breathwork and presence.', null, '2025-02-08', 'Morning session, Chennai', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-02-08T00:00:00Z'),
  ('sahana-focus-01', null, 'sahana', '{focus,meditate}', '{bittersweet,flowing,rain}', 'An overcast afternoon Sahana with a gentle ache. The phrases flow continuously, creating a backdrop that sustains attention without demanding it.', null, '2024-12-18', 'Overcast afternoon, Portland', 2700, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-12-18T00:00:00Z'),
  ('sahana-sleep-01', null, 'sahana', '{sleep}', '{tender,surrender,new year}', 'A New Year''s evening Sahana — tender, unhurried, winding down. Recorded as the year turned over, carrying a sense of release.', null, '2025-01-01', 'New Year''s evening, home studio', 5400, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-01-01T00:00:00Z'),
  ('sahana-meditate-02', null, 'sahana', '{meditate}', '{ocean,expansive,surrender}', 'Sahana beside the ocean at Mahabalipuram. The waves provided a natural tanpura, and the phrases stretched longer than usual.', 'The shore temple was right there. Centuries of devotion soaked into the stone. I think the raga knew.', '2025-03-01', 'Beside the ocean, Mahabalipuram', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', false, '2025-03-01T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('hindolam-meditate-01', null, 'hindolam', '{meditate}', '{serene,pentatonic,effortless}', 'A courtyard Hindolam in Chennai. The pentatonic simplicity removes all tension — each phrase swings gently like a pendulum.', null, '2024-10-15', 'Courtyard session, Chennai', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-10-15T00:00:00Z'),
  ('hindolam-focus-01', 'Hindolam — Morning Clarity', 'hindolam', '{focus}', '{clarity,bright,morning}', 'A crisp morning Hindolam with gentle percussion. The pentatonic structure keeps the mind clear without wandering.', null, '2025-01-05', 'First light, Portland', 2700, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-01-05T00:00:00Z'),
  ('hindolam-sleep-01', null, 'hindolam', '{sleep,meditate}', '{rain,gentle,dissolving}', 'A rainy evening Hindolam that dissolves gradually into near-silence. The rain on the studio roof became part of the texture.', null, '2025-02-10', 'Rainy evening, home studio', 5400, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-02-10T00:00:00Z'),
  ('hindolam-meditate-02', null, 'hindolam', '{meditate}', '{gratitude,grounding,holiday}', 'A Thanksgiving morning session. The raga felt like gratitude — simple, warm, complete in itself.', null, '2024-11-28', 'Thanksgiving morning, Portland', 1800, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-11-28T00:00:00Z'),
  ('hindolam-focus-02', null, 'hindolam', '{focus}', '{fog,steady,quiet}', 'Recorded on a foggy Sellwood morning. A steady, unadorned Hindolam that sits quietly beside you while you work.', null, '2025-03-15', 'Foggy dawn, Sellwood', 2700, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', false, '2025-03-15T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('mohanam-focus-01', null, 'mohanam', '{focus}', '{bright,energizing,joyful}', 'A sunny afternoon Mohanam full of ascending phrases. Bright and energizing without tipping into restlessness.', null, '2024-11-03', 'Sunny afternoon, Portland', 2700, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-11-03T00:00:00Z'),
  ('mohanam-focus-02', 'Mohanam — Bright Focus', 'mohanam', '{focus,meditate}', '{uplifting,percussion,weekend}', 'A weekend session with strong percussion. The rhythm and melody together create a joyful momentum that carries deep work.', null, '2025-01-22', 'Weekend session, home studio', 2700, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-01-22T00:00:00Z'),
  ('mohanam-meditate-01', null, 'mohanam', '{meditate}', '{garden,birdsong,gentle}', 'A garden session in Chennai where birdsong wove through the phrases. A gentler Mohanam, more contemplative than bright.', 'The crows and mynahs kept joining in. At some point I stopped trying to play over them and started playing with them.', '2025-02-18', 'Garden session, Chennai', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-02-18T00:00:00Z'),
  ('mohanam-focus-03', null, 'mohanam', '{focus}', '{cozy,steady,afternoon}', 'A compact afternoon Mohanam recorded at a quiet corner table. Steady and contained — good for short focus sprints.', null, '2024-12-10', 'Coffee shop corner, Sellwood', 1800, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-12-10T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('kalyani-focus-01', null, 'kalyani', '{focus}', '{expansive,bright,year-end}', 'A year-end Kalyani session with wide, ascending phrases. The expansiveness of the raga matches the reflective mood of December.', null, '2024-12-28', 'Year-end session, Portland', 2700, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-12-28T00:00:00Z'),
  ('kalyani-meditate-01', 'Kalyani at Twilight', 'kalyani', '{meditate}', '{twilight,devotional,spacious}', 'Recorded after visiting the Ranganathaswamy temple in Trichy. The evening light and the scale of the temple infused the session.', 'The gopuram was still glowing when I sat down to play. Some ragas carry the architecture of the spaces they''re played in.', '2025-02-05', 'Temple visit aftermath, Trichy', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-02-05T00:00:00Z'),
  ('kalyani-focus-02', null, 'kalyani', '{focus,meditate}', '{snow,quiet,mountain}', 'A snowy morning Kalyani from a cabin near Mt. Hood. The silence of snow and the brightness of the raga in perfect balance.', null, '2025-01-15', 'Snowy morning, Mt. Hood cabin', 2700, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', false, '2025-01-15T00:00:00Z'),
  ('kalyani-sleep-01', null, 'kalyani', '{sleep}', '{late night,unwinding,soft}', 'A rare late-night Kalyani, slower and softer than its usual bright character. The expansiveness here becomes a kind of gentle floating.', null, '2025-03-05', 'Late night improvisation, home studio', 5400, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-03-05T00:00:00Z');
insert into tracks (id, title, ragam_id, scenarios, tags, description, artist_note, recorded_date, location, duration, audio_url, free, created_at) values
  ('todi-meditate-01', 'Todi — First Light', 'todi', '{meditate}', '{intense,predawn,stillness}', 'A predawn Todi of quiet intensity. Each phrase is placed with deliberation, demanding and rewarding full attention.', 'Todi asks you to slow down completely. You can''t rush it. The raga won''t let you.', '2024-10-30', 'Predawn session, Chennai', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-10-30T00:00:00Z'),
  ('todi-focus-01', null, 'todi', '{focus}', '{deliberate,deep,saturday}', 'A quiet Saturday Todi. The deliberate pace creates a container for deep, sustained work — not background music, but a companion.', null, '2025-01-18', 'Quiet Saturday, Portland', 2700, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2025-01-18T00:00:00Z'),
  ('todi-meditate-02', null, 'todi', '{meditate,focus}', '{temple bells,morning,sacred}', 'Todi after the morning temple bells in Mylapore. The raga carries the weight of centuries of morning practice in this neighborhood.', null, '2025-02-22', 'After temple bells, Mylapore', 3600, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', false, '2025-02-22T00:00:00Z'),
  ('todi-sleep-01', null, 'todi', '{sleep}', '{midnight,sparse,dissolving}', 'A midnight Todi — unusual for a morning raga, but the sparse phrasing and long silences work beautifully for winding down.', null, '2024-12-15', 'Midnight session, home studio', 5400, '/audio/focus/Bhairavi_440Hz_with_percussion.m4a', true, '2024-12-15T00:00:00Z');
